559		refSpecs := make([]string, 0, len(archives))
560		archiveTmpRefs := make([]plumbing.ReferenceName, 0, len(archives))
561	
562		for _, archive := range archives {
563			archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + archive)
564			archiveTmpRef := archiveTmpRefName(archive)
565			refSpecs = append(refSpecs, fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef))
566			archiveTmpRefs = append(archiveTmpRefs, archiveTmpRef)
567		}
568	
569		// These archive commits are read immediately through go-git for tree
570		// flattening, so fetch the complete refs rather than blobless packfiles.
571		if output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
572			Remote:    fetchTarget,
573			RefSpecs:  refSpecs,
574			NoTags:    true,
575			NoFilter:  true,
576			ExtraArgs: []string{"--no-write-fetch-head"},
577		}); fetchErr != nil {
578			if repo, openErr := OpenRepository(ctx); openErr == nil {
579				cleanupFetchedArchiveTmpRefs(repo, archiveTmpRefs)
580			}
581			return fetchedRemoteRotationArchive{}, fmt.Errorf("fetch archived generations failed: %s", output)
582		}
583	
584		repo, err := OpenRepository(ctx)
585		if err != nil {
586			return fetchedRemoteRotationArchive{}, fmt.Errorf("reopen repository after fetching archived generations: %w", err)
587		}
588		tmpRefsToCleanup := archiveTmpRefs
589		defer func() {
590			cleanupFetchedArchiveTmpRefs(repo, tmpRefsToCleanup)
591		}()
592	
593		localCurrentAncestors, ok := currentGenerationAncestors(ctx, repo, localCurrentHash)
594		if !ok {
595			return fetchedRemoteRotationArchive{}, errors.New("failed to read local /full/current history")
596		}
597		for _, archive := range archives {
598			fetched, err := readFetchedRemoteRotationArchive(repo, archive)
599			if err != nil {
600				return fetchedRemoteRotationArchive{}, err
601			}
602			if archiveSharesHistoryWithCurrentGeneration(ctx, repo, localCurrentAncestors, fetched.ref.Hash()) {
603				tmpRefsToCleanup = removeRef(tmpRefsToCleanup, fetched.tmpRefName)
604				return fetched, nil
605			}
606		}
607		return fetchedRemoteRotationArchive{}, errors.New("no remote archive shares history with local /full/current")
608	}
