812	// Pushes active refs in one git push. Pending full-generation publications are
813	// handled separately before /full/current recovery.
814	func pushV2Refs(ctx context.Context, target string) {
815		repo, err := OpenRepository(ctx)
816		if err != nil {
817			printV2PushFailures(ctx, target, nil, []error{fmt.Errorf("open repository: %w", err)}, false)
818			return
819		}
820		store := checkpoint.NewV2GitStore(repo, target)
821	
822		refs := v2RefsToPush(repo)
823		pendingPublications, pendingReadErr := readPendingV2FullGenerationPublications(ctx, store)
824		if pendingReadErr != nil {
825			printV2PushFailures(ctx, target, nil, []error{pendingReadErr}, false)
826			return
827		}
828	
829		if len(refs) == 0 && len(pendingPublications) == 0 {
830			return
831		}
832	
833		fmt.Fprintln(os.Stderr, "[entire] Syncing and pushing v2 checkpoints...")
834		pushNames := shortRefNames(refs)
835		if len(pushNames) == 0 {
836			pushNames = []string{"pending v2/full generations"}
837		}
838		fmt.Fprintf(os.Stderr, "[entire] Pushing %s...\n", strings.Join(pushNames, ", "))
839	
840		var failures []error
841		var successfulRefs []plumbing.ReferenceName
842		pushedContent := false
843	
844		pendingPublicationResult, pendingPublishErr := publishPendingV2FullGenerationPublications(ctx, repo, store, target, pendingPublications)
845		successfulRefs = append(successfulRefs, pendingPublicationResult.successfulRefs...)
846		if len(pendingPublicationResult.successfulRefs) > 0 {
847			pushedContent = true
848		}
849		if pendingPublishErr != nil {
850			failures = append(failures, fmt.Errorf("couldn't publish pending v2 full generation refs: %w", pendingPublishErr))
851			printV2PushFailures(ctx, target, successfulRefs, failures, pushedContent)
852			return
853		}
854		if pendingPublicationResult.fullCurrentResetHandled {
855			refs = removeRef(refs, plumbing.ReferenceName(paths.V2FullCurrentRefName))
856		}
857	
858		results := pushV2RefsWithRecovery(ctx, target, refs)
859		for _, result := range results {
860			if result.err != nil {
861				failures = append(failures, result.err)
862				continue
863			}
864			successfulRefs = appendUniqueRef(successfulRefs, result.refName)
865			if !result.result.upToDate {
866				pushedContent = true
867			}
868		}
869	
870		if len(failures) > 0 {
871			printV2PushFailures(ctx, target, successfulRefs, failures, pushedContent)
872			return
873		}
874	
875		fmt.Fprintln(os.Stderr, "[entire] All v2 checkpoints pushed")
876		if pushedContent {
877			printSettingsCommitHint(ctx, target)
878		}
879		printCheckpointsV2MigrationHint(ctx)
880	}
