136	// settingsHintOnce ensures the settings commit hint prints at most once per process.
137	var settingsHintOnce sync.Once
138	
139	// checkpointsV2MigrationHintOnce ensures the checkpoints v2 migration hint prints at most once per process.
140	var checkpointsV2MigrationHintOnce sync.Once
141	
142	// printSettingsCommitHint prints a hint after a successful checkpoint remote push
143	// when the committed .entire/settings.json does not contain a checkpoint_remote config.
144	// entire.io discovers the external checkpoint repo by reading the committed project
145	// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
146	// (not just in settings.local.json or uncommitted local changes).
147	// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
148	// single pre-push invocation.
149	func printSettingsCommitHint(ctx context.Context, target string) {
150		if !remote.IsURL(target) {
151			return
152		}
153		settingsHintOnce.Do(func() {
154			if isCheckpointRemoteCommitted(ctx) {
155				return
156			}
157			fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
158		})
159	}
160	
161	// printCheckpointsV2MigrationHint prints a hint when the committed project
162	// settings enable checkpoints_version: 2 AND there are v1 checkpoints that have
163	// not yet been mirrored into v2. Suppressed when v2 already has every v1
164	// checkpoint (nothing to migrate) so the hint does not become noise once the
165	// migration is done.
166	func printCheckpointsV2MigrationHint(ctx context.Context) {
167		checkpointsV2MigrationHintOnce.Do(func() {
168			if !isCheckpointsVersion2Committed(ctx) {
169				return
170			}
171			if !hasUnmigratedV1Checkpoints(ctx) {
172				return
173			}
174			fmt.Fprintln(os.Stderr, "[entire] Note: .entire/settings.json sets checkpoints_version: 2. Run 'entire migrate --checkpoints v2' to migrate existing checkpoints to v2.")
175			fmt.Fprintln(os.Stderr, "[entire] Use 'entire migrate --checkpoints v2 --force' to rewrite all checkpoints in v2.")
176		})
177	}
178	
179	// hasUnmigratedV1Checkpoints reports whether any v1 checkpoint has no matching
180	// entry in v2. Any failure opening the repo or listing either store is treated
181	// as "no migration needed" so we stay silent instead of printing a speculative
182	// hint — the hint is advisory and should never be the reason a push gets noisy.
183	func hasUnmigratedV1Checkpoints(ctx context.Context) bool {
184		repo, err := OpenRepository(ctx)
185		if err != nil {
186			return false
187		}
188		v1Store := checkpoint.NewGitStore(repo)
189		v1List, err := v1Store.ListCommitted(ctx)
190		if err != nil || len(v1List) == 0 {
191			return false
192		}
193		v2List, err := checkpoint.NewV2GitStore(repo, "").ListCommitted(ctx)
194		if err != nil {
195			return false
196		}
197		v2Set := make(map[string]struct{}, len(v2List))
198		for _, info := range v2List {
199			v2Set[info.CheckpointID.String()] = struct{}{}
200		}
201		for _, info := range v1List {
202			if _, ok := v2Set[info.CheckpointID.String()]; !ok {
203				summary, readErr := v1Store.ReadCommitted(ctx, info.CheckpointID)
204				if readErr != nil || summary == nil {
205					continue
206				}
207				return true
208			}
209		}
210		return false
211	}
