213	// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
214	// at HEAD contains a valid checkpoint_remote configuration. This is the true
215	// discoverability check: entire.io reads from committed project settings, not from
216	// local overrides or uncommitted changes.
217	func isCheckpointRemoteCommitted(ctx context.Context) bool {
218		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
219		output, err := cmd.Output()
220		if err != nil {
221			return false // file doesn't exist at HEAD
222		}
223		// Parse the committed content and check for checkpoint_remote
224		committed, err := settings.LoadFromBytes(output)
225		if err != nil {
226			return false
227		}
228		return committed.GetCheckpointRemote() != nil
229	}
