585	// createMergeCommitCommon creates a merge commit with multiple parents.
586	func createMergeCommitCommon(ctx context.Context, repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
587		authorName, authorEmail := GetGitAuthorFromRepo(repo)
588		now := time.Now()
589		sig := object.Signature{
590			Name:  authorName,
591			Email: authorEmail,
592			When:  now,
593		}
594	
595		commit := &object.Commit{
596			TreeHash:     treeHash,
597			ParentHashes: parents,
598			Author:       sig,
599			Committer:    sig,
600			Message:      message,
601		}
602	
603		checkpoint.SignCommitBestEffort(ctx, commit)
604	
605		obj := repo.Storer.NewEncodedObject()
606		if err := commit.Encode(obj); err != nil {
607			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
608		}
609	
610		hash, err := repo.Storer.SetEncodedObject(obj)
611		if err != nil {
612			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
613		}
614	
615		return hash, nil
616	}
