346	func parsePushRefStatusLine(line string) (v2RefPushResult, bool) {
347		fields := strings.Split(line, "\t")
348		if len(fields) < 2 || fields[0] == "" {
349			return v2RefPushResult{}, false
350		}
351	
352		refName, ok := pushStatusRef(fields[1])
353		if !ok {
354			return v2RefPushResult{}, false
355		}
356	
357		switch fields[0][0] {
358		case '!':
359			err := classifyPushOutput(strings.Join(fields[2:], "\t"))
360			return v2RefPushResult{
361				refName: refName,
362				err:     fmt.Errorf("failed to push %s: %w", shortRefName(refName), err),
363			}, true
364		case '=':
365			return v2RefPushResult{
366				refName: refName,
367				result:  pushResult{upToDate: true},
368			}, true
369		default:
370			return v2RefPushResult{refName: refName}, true
371		}
372	}
