399		tmpRefName := plumbing.ReferenceName("refs/entire-fetch-tmp/" + tmpRefSuffix)
400		refSpec := fmt.Sprintf("+%s:%s", refName, tmpRefName)
401	
402		// Recovery flattens fetched trees recursively, so it needs a complete object
403		// graph instead of the normal blobless sync fetch.
404		if output, err := remote.Fetch(ctx, remote.FetchOptions{
405			Remote:    fetchTarget,
406			RefSpecs:  []string{refSpec},
407			NoTags:    true,
408			NoFilter:  true,
409			ExtraArgs: []string{"--no-write-fetch-head"},
410		}); err != nil {
411			return fmt.Errorf("fetch failed: %s", output)
412		}
413	
414		repo, err := OpenRepository(ctx)
415		if err != nil {
416			return fmt.Errorf("failed to open repository: %w", err)
417		}
418		defer func() {
419			_ = repo.Storer.RemoveReference(tmpRefName) //nolint:errcheck // cleanup is best-effort
420		}()
421	
422		// Check for rotation conflict on /full/current
423		if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
424			remoteRotationArchives, detectErr := detectRemoteRotationArchives(ctx, target, repo)
425			if detectErr == nil && len(remoteRotationArchives) > 0 {
