427			}
428		}
429	
430		// Standard tree merge (no rotation detected)
431		localRef, err := repo.Reference(refName, true)
432		if err != nil {
433			return fmt.Errorf("failed to get local ref: %w", err)
434		}
435		localCommit, err := repo.CommitObject(localRef.Hash())
436		if err != nil {
437			return fmt.Errorf("failed to get local commit: %w", err)
438		}
439		localTree, err := localCommit.Tree()
