46	func (s *V2GitStore) AppendPendingFullGenerationPublications(ctx context.Context, publications []PendingV2FullGenerationPublication) error {
47		if len(publications) == 0 {
48			return nil
49		}
50		return s.withPendingFullGenerationPublicationLock(ctx, func() error {
51			state, err := s.readPendingFullGenerationPublicationState(ctx)
52			if err != nil {
53				return err
54			}
55			state.Version = pendingV2FullGenerationPublicationVersion
56			state.Publications = append(state.Publications, publications...)
57			return s.writePendingFullGenerationPublicationState(ctx, state)
58		})
