91	func removePendingFullGenerationPublications(current, remove []PendingV2FullGenerationPublication) []PendingV2FullGenerationPublication {
92		removeCounts := make(map[PendingV2FullGenerationPublication]int, len(remove))
93		for _, publication := range remove {
94			removeCounts[comparablePendingFullGenerationPublication(publication)]++
95		}
96	
97		remaining := make([]PendingV2FullGenerationPublication, 0, len(current))
98		for _, publication := range current {
99			key := comparablePendingFullGenerationPublication(publication)
100			if removeCounts[key] > 0 {
101				removeCounts[key]--
102				continue
103			}
104			remaining = append(remaining, publication)
105		}
106		return remaining
107	}
