152		var state pendingV2FullGenerationPublicationState
153		if err := json.Unmarshal(data, &state); err != nil {
154			return pendingV2FullGenerationPublicationState{}, fmt.Errorf("parse pending v2 full generation publications: %w", err)
155		}
156		if state.Version != pendingV2FullGenerationPublicationVersion {
157			return pendingV2FullGenerationPublicationState{}, fmt.Errorf("unsupported pending v2 full generation publication version %d", state.Version)
158		}
159		return state, nil
