673	// handleRotationConflict handles the case where remote /full/current was rotated.
674	// Merges local /full/current into the related remote archived generation to avoid
675	// duplicating checkpoint data, then adopts remote's /full/current as local.
676	func handleRotationConflict(ctx context.Context, target, fetchTarget string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteRotationArchives []string) error {
677		localRef, err := repo.Reference(refName, true)
678		if err != nil {
679			return fmt.Errorf("failed to get local ref: %w", err)
680		}
681	
682		archive, err := fetchRelatedRemoteRotationArchive(ctx, fetchTarget, remoteRotationArchives, localRef.Hash())
683		if err != nil {
684			return fmt.Errorf("failed to find related archived generation: %w", err)
685		}
686		// fetchRelatedRemoteRotationArchive fetches via git CLI, so continue with
687		// the fresh go-git handle it used to avoid stale pack indexes.
688		repo = archive.repo
689		defer func() {
690			_ = repo.Storer.RemoveReference(archive.tmpRefName) //nolint:errcheck // cleanup is best-effort
691		}()
692	
693		localRef, err = repo.Reference(refName, true)
694		if err != nil {
695			return fmt.Errorf("failed to get local ref: %w", err)
696		}
697		localCommit, err := repo.CommitObject(localRef.Hash())
698		if err != nil {
699			return fmt.Errorf("failed to get local commit: %w", err)
700		}
701		localTree, err := localCommit.Tree()
702		if err != nil {
703			return fmt.Errorf("failed to get local tree: %w", err)
704		}
705	
706		// Tree-merge local /full/current into archived generation.
707		// Git content-addressing deduplicates shared shard paths automatically.
708		entries := make(map[string]object.TreeEntry)
709		if err := checkpoint.FlattenTree(repo, archive.tree, "", entries); err != nil {
710			return fmt.Errorf("failed to flatten archive tree: %w", err)
711		}
712		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
713			return fmt.Errorf("failed to flatten local tree: %w", err)
714		}
715	
716		// Update generation.json timestamps if present in the merged tree.
717		// Use the local /full/current HEAD commit time as the newest checkpoint time
718		// (more accurate than time.Now() for cleanup scheduling).
719		if genEntry, exists := entries[paths.GenerationFileName]; exists {
720			if updatedEntry, updateErr := updateGenerationTimestamps(repo, genEntry.Hash, localCommit.Committer.When.UTC()); updateErr == nil {
721				entries[paths.GenerationFileName] = updatedEntry
722			} else {
723				logging.Warn(ctx, "rotation recovery: failed to update generation timestamps, using stale values",
724					slog.String("error", updateErr.Error()),
725				)
726			}
727		}
728	
729		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
730		if err != nil {
731			return fmt.Errorf("failed to build merged tree: %w", err)
732		}
733	
734		// Create commit parented on archive's commit (fast-forward)
735		mergeCommitHash, err := createMergeCommitCommon(ctx, repo, mergedTreeHash,
736			[]plumbing.Hash{archive.ref.Hash()},
737			"Merge local checkpoints into archived generation")
738		if err != nil {
739			return fmt.Errorf("failed to create merge commit: %w", err)
740		}
741	
742		// Update local archived ref and push it
743		newArchiveRef := plumbing.NewHashReference(archive.refName, mergeCommitHash)
744		if err := repo.Storer.SetReference(newArchiveRef); err != nil {
745			return fmt.Errorf("failed to update archive ref: %w", err)
746		}
747	
748		if pushErr := tryPushRef(ctx, target, archive.refName); pushErr != nil {
749			return fmt.Errorf("failed to push updated archive: %w", pushErr)
750		}
751	
752		// Adopt remote's /full/current as local
753		remoteRef, err := repo.Reference(tmpRefName, true)
754		if err != nil {
755			return fmt.Errorf("failed to get fetched /full/current: %w", err)
756		}
757		adoptedRef := plumbing.NewHashReference(refName, remoteRef.Hash())
758		if err := repo.Storer.SetReference(adoptedRef); err != nil {
759			return fmt.Errorf("failed to adopt remote /full/current: %w", err)
760		}
761	
762		return nil
763	}
