765	// updateGenerationTimestamps reads generation.json from a blob, updates
766	// newest_checkpoint_at if the provided newestFromLocal is newer, and returns
767	// an updated tree entry. Uses the local commit timestamp rather than
768	// time.Now() so cleanup scheduling reflects actual checkpoint creation time.
769	func updateGenerationTimestamps(repo *git.Repository, genBlobHash plumbing.Hash, newestFromLocal time.Time) (object.TreeEntry, error) {
770		blob, err := repo.BlobObject(genBlobHash)
771		if err != nil {
772			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob: %w", err)
773		}
774		reader, err := blob.Reader()
775		if err != nil {
776			return object.TreeEntry{}, fmt.Errorf("failed to open generation blob reader: %w", err)
777		}
778		defer reader.Close()
779	
780		data, err := io.ReadAll(reader)
781		if err != nil {
782			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob data: %w", err)
783		}
784	
785		var gen checkpoint.GenerationMetadata
786		if err := json.Unmarshal(data, &gen); err != nil {
787			return object.TreeEntry{}, fmt.Errorf("failed to parse generation.json: %w", err)
788		}
789	
790		if newestFromLocal.After(gen.NewestCheckpointAt) {
791			gen.NewestCheckpointAt = newestFromLocal
792		}
793	
794		updatedData, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
795		if err != nil {
796			return object.TreeEntry{}, fmt.Errorf("failed to marshal generation.json: %w", err)
797		}
798	
799		newBlobHash, err := checkpoint.CreateBlobFromContent(repo, updatedData)
800		if err != nil {
801			return object.TreeEntry{}, fmt.Errorf("failed to create generation blob: %w", err)
802		}
803	
804		return object.TreeEntry{
805			Name: paths.GenerationFileName,
806			Mode: filemode.Regular,
807			Hash: newBlobHash,
808		}, nil
809	}

