// NextGenerationNumberConsideringRemote returns max(localMax, remoteMax) + 1.
//
// localMax is derived from local refs (same as NextGenerationNumber).
// remoteMax is derived from a 30-second `git ls-remote` for the v2 /full/*
// refs on s.FetchRemote. Any failure — ls-remote error, parse error, no
// remote configured — falls back to localMax + 1 with a debug log; the
// push-time merge path remains the safety net for the rare race where two
// machines pre-check the same remote and both pick the same next number.
func (s *V2GitStore) NextGenerationNumberConsideringRemote(ctx context.Context) (int, error) {
	archived, err := s.ListArchivedGenerations()
	if err != nil {
		return 0, err
	}
	localMax := maxGenerationNumber(archived)

	target := s.FetchRemote
	if target == "" {
		return localMax + 1, nil
	}

	remoteMax, ok := s.remoteMaxGenerationNumber(ctx, target)
	if !ok {
		return localMax + 1, nil
	}

	if remoteMax > localMax {
		logging.Info(ctx, "rotation: deferred to remote generation count",
			slog.Int("archive_number", remoteMax+1),
			slog.Int("local_max", localMax),
			slog.Int("remote_max", remoteMax),
		)
		return remoteMax + 1, nil
	}
	return localMax + 1, nil
}

// remoteMaxGenerationNumber runs `git ls-remote` against the configured
// fetch remote and returns the maximum parseable generation suffix it sees.
// Returns false on any error so the caller can fall back to local-only
// numbering — pre-rotation remote awareness is opportunistic, not required.
func (s *V2GitStore) remoteMaxGenerationNumber(ctx context.Context, target string) (int, bool) {
	dir, dirErr := s.worktreeDir()
	if dirErr != nil {
		logging.Debug(ctx, "rotation: failed to resolve worktree dir for ls-remote",
			slog.String("error", dirErr.Error()),
		)
		return 0, false
	}

	lsCtx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()

	output, err := remote.LsRemoteInDir(lsCtx, dir, target, paths.V2FullRefPrefix+"*")
	if err != nil {
		logging.Debug(ctx, "rotation: ls-remote for v2 full refs failed",
			slog.String("target", target),
			slog.String("error", err.Error()),
		)
		return 0, false
	}

	remoteMax := 0
	for suffix := range ParseRemoteGenerationRefs(output) {
		n, parseErr := strconv.Atoi(suffix)
		if parseErr != nil {
			continue
		}
		if n > remoteMax {
			remoteMax = n
		}
	}
	return remoteMax, true
}

func (s *V2GitStore) worktreeDir() (string, error) {
	worktree, err := s.repo.Worktree()
	if err != nil {
		return "", fmt.Errorf("open worktree: %w", err)
	}
	root := worktree.Filesystem().Root()
	if root == "" {
		return "", errors.New("empty worktree root")
	}
	return root, nil
}

